import * as THREE from 'three/webgpu';
import { texture, uv, positionLocal, vec2, vec3, float, uniform, mix, MeshPhysicalNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-features-divider';
  group.position.set(-1.25, -0.19999999999999996, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const colorMap = ctx.textureLoader.load('/prism-mock/home/nodes/parallax-stack.png');
  const depthMap = ctx.textureLoader.load('/prism-mock/home/nodes/parallax-stack.depth.png');
  colorMap.colorSpace = THREE.SRGBColorSpace;

  const geometry = new THREE.PlaneGeometry(3.0, 0.14, 64, 64);

  const parallaxOffset = uniform(vec2(0, 0));
  const displacementStrength = uniform(float(0.03));
  const hoverLift = uniform(float(0));

  const material = new MeshPhysicalNodeMaterial();
  const baseColor = texture(colorMap, uv().add(parallaxOffset));
  const depthSample = texture(depthMap, uv());

  material.colorNode = mix(
    baseColor,
    vec3(1.0, 0.164, 0.219),
    depthSample.r.mul(0.15)
  );

  material.positionNode = positionLocal.add(
    vec3(0.0, 0.0, depthSample.r.mul(displacementStrength).add(hoverLift))
  );

  material.metalness = 0.5;
  material.roughness = 0.55;
  material.clearcoat = 0.2;
  material.clearcoatRoughness = 0.3;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'divider-plane';
  group.add(mesh);

  // Center jewel: small accent sphere
  const jewelGeo = new THREE.SphereGeometry(0.045, 32, 32);
  const jewelMat = new MeshPhysicalNodeMaterial();
  jewelMat.colorNode = vec3(1.0, 0.164, 0.219);
  jewelMat.metalness = 0.55;
  jewelMat.roughness = 0.35;
  jewelMat.clearcoat = 0.25;
  const jewel = new THREE.Mesh(jewelGeo, jewelMat);
  jewel.position.set(0, 0, 0.04);
  jewel.name = 'center-jewel';
  group.add(jewel);

  // Subtle parallax on pointer move
  const onPointerMove = (nx, ny) => {
    gsap.to(parallaxOffset.value, {
      x: nx * 0.015,
      y: ny * 0.015,
      duration: 0.6,
      ease: 'power2.out'
    });
  };

  let hoverTl = null;
  const onHoverIn = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, { y: group.position.y + 0.15, duration: 0.7, ease: 'power3.out' });
    hoverTl.to(hoverLift, { value: 0.01, duration: 0.7, ease: 'power3.out' }, 0);
  };

  const baseY = -0.19999999999999996;
  const onHoverOut = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, { y: baseY, duration: 0.5, ease: 'power2.out' });
    hoverTl.to(hoverLift, { value: 0, duration: 0.5, ease: 'power2.out' }, 0);
  };

  const onClick = () => {
    gsap.timeline()
      .to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' })
      .to(group.scale, { x: 1, y: 1, z: 1, duration: 0.15, ease: 'back.out' });

    if (ctx.emit) {
      ctx.emit('hub-features.select', { source: 'ornamental-divider' });
    }
  };

  group.userData.handlers = {
    onPointerMove,
    onHoverIn,
    onHoverOut,
    onClick
  };

  group.userData.cleanup = () => {
    gsap.killTweensOf(parallaxOffset.value);
    gsap.killTweensOf(hoverLift);
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    if (hoverTl) hoverTl.kill();

    geometry.dispose();
    material.dispose();
    jewelGeo.dispose();
    jewelMat.dispose();
    colorMap.dispose();
    depthMap.dispose();
  };

  return group;
}
